/* recipe: base */
:root {
  --accent: #4f6bed;
  --bg: #f4f6fb;
  --fg: #1d2433;
  --card: #ffffff;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 2rem 1rem;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  line-height: 1.5;
  background: var(--bg);
  color: var(--fg);
}

/* recipe: card */
.card {
  background: var(--card);
  margin: 2rem auto;
  padding: 2rem;
  width: min(92vw, 420px);
  text-align: center;
  border-radius: 16px;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.12);
}

button {
  background: var(--accent);
  color: #ffffff;
  border: 0;
  border-radius: 10px;
  padding: 0.6rem 1.1rem;
  font-size: 1rem;
  cursor: pointer;
  transition: transform 0.15s ease, opacity 0.15s ease;
}

button:hover {
  transform: translateY(-2px);
  opacity: 0.9;
}

button.ghost {
  background: transparent;
  color: var(--accent);
  border: 2px solid var(--accent);
}

/* recipe: page */
